{
  "description": "The creature is a large, powerfully built quadrupedal mammal resembling a big cat, shown in side view standing on a flat light surface and turned to face slightly toward the viewer. Its body is long and muscular with a tawny golden-brown coat that is paler cream on the chest, underbelly and chin, and bears faint to moderate dark striping. It has a broad feline head with a short muzzle, a shaggy ruff of longer fur around the neck and chest, four thick legs ending in large paws, and a short thin tail with a dark tip extending from the rear. The overall impression is of a lion-like head and build combined with tiger-like striping.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad feline head with a short blunt muzzle, dark nose, white to cream fur on the chin and around the mouth, long white whiskers, amber-brown eyes with dark pupils and white markings below the eyes, and tawny fur with faint dark stripes on the forehead",
      "where": "at the front of the body, held above the forelegs and turned to face forward toward the viewer"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears with tufted edges, tawny on the outside with a dark patch on the back of each ear",
      "where": "on top of the head, one on each side"
    },
    {
      "part": "mane",
      "looks_like": "a shaggy ruff of longer, slightly wavy tawny and cream fur, thicker and more textured than the short body coat",
      "where": "encircling the neck, under the chin, and extending down the front of the chest"
    },
    {
      "part": "legs",
      "looks_like": "four thick, muscular legs covered in short tawny fur with distinct dark horizontal stripes, especially pronounced on the lower hind legs",
      "where": "two forelegs under the chest at the front of the body and two hind legs under the hips at the rear, supporting the body in a standing pose"
    },
    {
      "part": "feet",
      "looks_like": "four large rounded paws with visible toe pads and short blunt claws, light tan to cream with darker fur between the toes",
      "where": "at the bottom ends of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a short, slender tail with alternating light and dark striped bands and a dark bushy tip",
      "where": "protruding from the rear of the body at the rump, held low and extending slightly outward to the left"
    },
    {
      "part": "markings",
      "looks_like": "faint to moderate dark brown to black tiger-like vertical and horizontal stripes over the tawny base coat, more concentrated and darker on the back, sides, hindquarters, lower legs and tail, with a pale cream underbelly and chest",
      "where": "across the torso, back, sides, hindquarters, legs and tail"
    }
  ],
  "attached_objects": [],
  "animals": [
    "lion",
    "tiger"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0
}
